defmodule Messaging.Suspension.SignatureTest do
  use ExUnit.Case, async: true

  alias Messaging.Suspension.Signature

  @secret "shared-secret"

  # Generated by the Go `Sign` of events-contract/admin (UserSuspended and
  # UserReactivated, secret "shared-secret"); this is what admin puts on the wire.
  @go_suspended %{
    routing_key: "admin.user_suspended",
    event_id: "evt-1",
    occurred_at: "2026-01-01T10:30:00.123456789Z",
    user_id: "user-1",
    version: 3,
    signature: "bee91d28c7bb47c28efca3bf863822a6ac35c0d748996b8e04236044b947c2f8"
  }
  @go_reactivated %{
    @go_suspended
    | routing_key: "admin.user_reactivated",
      signature: "6f783f3d02c7df2463fd031a61401674e91b5553540fdfbf5127d27d019be389"
  }
  @go_whole_second %{
    routing_key: "admin.user_suspended",
    event_id: "evt-2",
    occurred_at: "2026-10-15T12:00:00Z",
    user_id: "11111111-1111-4111-8111-111111111111",
    version: 7,
    signature: "19b879696983d128b56c85d0162b2ab5ac364d99e727439db2b6a3693710cf24"
  }

  describe "verify/2 with signatures generated by the Go contract" do
    test "accepts a UserSuspended signed by admin" do
      assert Signature.verify(@go_suspended, @secret)
    end

    test "accepts a UserReactivated signed by admin" do
      assert Signature.verify(@go_reactivated, @secret)
    end

    test "accepts an occurred_at without fraction, as Go trims the zeros" do
      assert Signature.verify(@go_whole_second, @secret)
    end

    test "sign/2 produces exactly what Go produced" do
      assert Signature.sign(Map.delete(@go_suspended, :signature), @secret) ==
               @go_suspended.signature
    end
  end

  describe "verify/2 rejects" do
    test "a different secret" do
      refute Signature.verify(@go_suspended, "other-secret")
    end

    test "an empty or missing secret, even with a signature that matches" do
      signature = Signature.sign(Map.delete(@go_suspended, :signature), "")
      refute Signature.verify(%{@go_suspended | signature: signature}, "")
      refute Signature.verify(@go_suspended, nil)
    end

    test "a signature of the other routing key (replay of a suspension as a reactivation)" do
      refute Signature.verify(%{@go_suspended | routing_key: "admin.user_reactivated"}, @secret)
      refute Signature.verify(%{@go_reactivated | routing_key: "admin.user_suspended"}, @secret)
    end

    for {field, value} <- [
          event_id: "evt-9",
          user_id: "user-2",
          version: 4,
          occurred_at: "2026-01-01T10:30:00.123456780Z"
        ] do
      test "a tampered #{field}" do
        refute Signature.verify(%{@go_suspended | unquote(field) => unquote(value)}, @secret)
      end
    end

    test "an occurred_at that means the same instant but is written differently" do
      refute Signature.verify(
               %{@go_suspended | occurred_at: "2026-01-01T10:30:00.1234567890Z"},
               @secret
             )

      refute Signature.verify(
               %{@go_suspended | occurred_at: "2026-01-01T07:30:00.123456789-03:00"},
               @secret
             )
    end

    test "a missing, empty or non hexadecimal signature" do
      refute Signature.verify(Map.delete(@go_suspended, :signature), @secret)
      refute Signature.verify(%{@go_suspended | signature: ""}, @secret)
      refute Signature.verify(%{@go_suspended | signature: nil}, @secret)
      refute Signature.verify(%{@go_suspended | signature: "zz"}, @secret)
    end

    test "an uppercase signature, as the contract is lowercase hex" do
      upcased = String.upcase(@go_suspended.signature)
      refute Signature.verify(%{@go_suspended | signature: upcased}, @secret)
    end

    test "fields of the wrong type" do
      refute Signature.verify(%{@go_suspended | version: "3"}, @secret)
      refute Signature.verify(%{@go_suspended | user_id: nil}, @secret)
      refute Signature.verify(Map.delete(@go_suspended, :event_id), @secret)
    end
  end
end
